// Check if polygons are axis-aligned bounding box disjoint
auto aabbDisjoint = [](const std::vector<Point2d>& p1, const std::vector<Point2d>& p2) {
    double minX1 = std::numeric_limits<double>::max(), maxX1 = -std::numeric_limits<double>::max();
    double minY1 = std::numeric_limits<double>::max(), maxY1 = -std::numeric_limits<double>::max();
    double minX2 = std::numeric_limits<double>::max(), maxX2 = -std::numeric_limits<double>::max();
    double minY2 = std::numeric_limits<double>::max(), maxY2 = -std::numeric_limits<double>::max();

    for (const auto& p : p1) {
        minX1 = std::min(minX1, p.x());
        maxX1 = std::max(maxX1, p.x());
        minY1 = std::min(minY1, p.y());
        maxY1 = std::max(maxY1, p.y());
    }

    for (const auto& p : p2) {
        minX2 = std::min(minX2, p.x());
        maxX2 = std::max(maxX2, p.x());
        minY2 = std::min(minY2, p.y());
        maxY2 = std::max(maxY2, p.y());
    }

    return maxX1 < minX2 || maxX2 < minX1 || maxY1 < minY2 || maxY2 < minY1;
};

// Project polygon onto axis and return min/max of projection
auto projectPolygon = [](const std::vector<Point2d>& polygon, const Point2d& axis) {
    double minProj = std::numeric_limits<double>::max();
    double maxProj = -std::numeric_limits<double>::max();

    for (const auto& point : polygon) {
        double proj = point.x() * axis.x() + point.y() * axis.y();
        minProj = std::min(minProj, proj);
        maxProj = std::max(maxProj, proj);
    }

    return std::make_pair(minProj, maxProj);
};

// Check if projections overlap
auto projectionsOverlap = [](const std::pair<double, double>& proj1,
                            const std::pair<double, double>& proj2) {
    return !(proj1.second < proj2.first || proj2.second < proj1.first);
};

// Get edges of polygon
auto getEdges = [](const std::vector<Point2d>& polygon) {
    std::vector<Segment2d> edges;
    for (size_t i = 0; i < polygon.size(); ++i) {
        const auto& p1 = polygon[i];
        const auto& p2 = polygon[(i + 1) % polygon.size()];
        edges.emplace_back(p1, p2);
    }
    return edges;
};

// Get perpendicular axis from edge
auto getPerpendicularAxis = [](const Segment2d& edge) {
    double dx = edge.p2().x() - edge.p1().x();
    double dy = edge.p2().y() - edge.p1().y();
    return Point2d(-dy, dx);
};

// Check for intersection using Separating Axis Theorem
if (aabbDisjoint(P1.points(), P2.points())) {
    return false;
}

const auto edges1 = getEdges(P1.points());
const auto edges2 = getEdges(P2.points());

// Check all edges from both polygons as potential separating axes
for (const auto& edge : edges1) {
    const auto axis = getPerpendicularAxis(edge);
    const auto proj1 = projectPolygon(P1.points(), axis);
    const auto proj2 = projectPolygon(P2.points(), axis);

    if (!projectionsOverlap(proj1, proj2)) {
        return false;
    }
}

for (const auto& edge : edges2) {
    const auto axis = getPerpendicularAxis(edge);
    const auto proj1 = projectPolygon(P1.points(), axis);
    const auto proj2 = projectPolygon(P2.points(), axis);

    if (!projectionsOverlap(proj1, proj2)) {
        return false;
    }
}

// If no separating axis found, polygons intersect
return true;

